package com.game_manager.gm.document.storage;
import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import java.io.*; import java.nio.charset.StandardCharsets; import org.junit.jupiter.api.Test; import software.amazon.awssdk.core.ResponseInputStream; import software.amazon.awssdk.http.AbortableInputStream; import software.amazon.awssdk.services.s3.S3Client; import software.amazon.awssdk.services.s3.model.*;
class S3DocumentStorageTest {@Test void implementsPrivateObjectContract()throws Exception{S3Client client=mock(S3Client.class);when(client.putObject(any(PutObjectRequest.class),any(software.amazon.awssdk.core.sync.RequestBody.class))).thenReturn(PutObjectResponse.builder().build());when(client.headObject(any(HeadObjectRequest.class))).thenReturn(HeadObjectResponse.builder().build());byte[] bytes="s3 private".getBytes(StandardCharsets.UTF_8);when(client.getObject(any(GetObjectRequest.class))).thenReturn(new ResponseInputStream<>(GetObjectResponse.builder().build(),AbortableInputStream.create(new ByteArrayInputStream(bytes))));S3DocumentStorage storage=new S3DocumentStorage(client,"documents");StoredObject saved=storage.store("quarantine/id/object",new ByteArrayInputStream(bytes),bytes.length);assertThat(saved.size()).isEqualTo(bytes.length);assertThat(saved.checksumSha256()).hasSize(64);assertThat(storage.exists(saved.key())).isTrue();assertThat(storage.open(saved.key()).readAllBytes()).isEqualTo(bytes);storage.delete(saved.key());verify(client).deleteObject(any(DeleteObjectRequest.class));assertThatThrownBy(()->storage.open("../escape")).isInstanceOf(IllegalArgumentException.class);}}
